// 由官方 Codec Encoder 提取的 Audio8 TTS 0.1B 预设音色库
import { parseNpyInt64, type NpyInt64Matrix } from "./audio8TtsOnnx";

export interface Audio8VoiceDef {
  id: string;
  name: string;
  referenceText: string;
  gender: "female" | "male";
  lang: "zh" | "en";
  codesB64: string;
}

export const AUDIO8_PRESET_VOICES: Audio8VoiceDef[] = [
  {
    id: "zh_male_clear",
    name: "清爽男声（自然日常 · 中文）",
    referenceText: "像我早上用完，今天一整天都是清清爽爽的。这男士洗面奶我也用过不少，大多洗完之后脸上特别干，紧绷得慌，还有一股很重的酒精味儿。",
    gender: "male",
    lang: "zh",
    codesB64: "",
  },
  {
    id: "zh_female_calm",
    name: "沉稳女声（抒情叙事 · 中文）",
    referenceText: "很多年以后，当我再次回到那座城市，才发现记忆里的街道和真实的风景已经完全不同。",
    gender: "female",
    lang: "zh",
    codesB64: "",
  },
  {
    id: "zh_female_broadcast",
    name: "播音主播（标准电台 · 中文）",
    referenceText: "前往杭州的旅客请注意，检票口已经开放，请带好随身物品有序进站。",
    gender: "female",
    lang: "zh",
    codesB64: "",
  },
  {
    id: "en_female_warm",
    name: "美式英文（地道原声 · 英文）",
    referenceText: "The bakery opened before sunrise, and the first trays of bread were already cooling beside the window.",
    gender: "female",
    lang: "en",
    codesB64: "",
  },
];

const voiceMap = new Map<string, { codes: NpyInt64Matrix; referenceText: string }>();

function base64ToUint8Array(b64: string): Uint8Array {
  const bin = atob(b64);
  const bytes = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) {
    bytes[i] = bin.charCodeAt(i);
  }
  return bytes;
}

export function getAudio8Voice(id: string): { codes: NpyInt64Matrix; referenceText: string } | null {
  if (voiceMap.has(id)) return voiceMap.get(id)!;
  const def = AUDIO8_PRESET_VOICES.find((v) => v.id === id);
  if (!def) return null;
  const bytes = base64ToUint8Array(def.codesB64);
  const codes = parseNpyInt64(bytes);
  const result = { codes, referenceText: def.referenceText };
  voiceMap.set(id, result);
  return result;
}
